{{setVar 'id' (body 'id' (uuid))}}{{setVar 'item' (object id=@id name=(bodyRaw 'name') email=(bodyRaw 'email') active=(bodyRaw 'active') roleIds=(bodyRaw 'roleIds'))}}
{{#if (len (filter (dataRaw 'users') (object id=@item.id)))}}
{{#each (dataRaw 'users')}}{{#if (eq this.id @item.id)}}{{setData 'set' 'users' (concat '' @index) @item}}{{/if}}{{/each}}
{{else}}{{setData 'push' 'users' '' @item}}{{/if}}{{{data 'users'}}}

{{setVar 'id' (body 'id' (uuid))}}{{setVar 'item' (object id=@id name=(bodyRaw 'name') system=false permissions=(bodyRaw 'permissions'))}}
{{#if (len (filter (dataRaw 'roles') (object id=@item.id)))}}
{{#each (dataRaw 'roles')}}{{#if (eq this.id @item.id)}}{{setData 'set' 'roles' (concat '' @index) @item}}{{/if}}{{/each}}
{{else}}{{setData 'push' 'roles' '' @item}}{{/if}}{{{data 'roles'}}}

{{setData 'set' '_transaction' '' (jsonParse '{}')}}
{{setVar 'warehouseId' (bodyRaw 'warehouseId')}}{{setVar 'type' (bodyRaw 'type')}}
{{#unless (len (filter (dataRaw 'warehouses') (object id=@warehouseId status='active')))}}{{setData 'set' '_transaction' 'error' 'Select an active warehouse.'}}{{/unless}}
{{#unless (len (filter (array 'stock-in' 'stock-out') @type))}}{{setData 'set' '_transaction' 'error' 'Select stock-in or stock-out.'}}{{/unless}}
{{#unless (len (bodyRaw 'items'))}}{{setData 'set' '_transaction' 'error' 'Add at least one SKU.'}}{{/unless}}
{{setData 'set' '_transaction' 'inventory' (jsonParse (stringify (dataRaw 'inventory')))}}
{{setData 'set' '_transaction' 'movements' (array)}}
{{#each (bodyRaw 'items')}}
  {{setVar 'line' this}}{{setVar 'found' false}}
  {{#unless (gt this.quantity 0)}}{{setData 'set' '_transaction' 'error' 'Enter a positive whole quantity.'}}{{/unless}}
  {{#unless (eq (modulo this.quantity 1) 0)}}{{setData 'set' '_transaction' 'error' 'Enter a positive whole quantity.'}}{{/unless}}
  {{#each (dataRaw 'products')}}{{#if (len (filter this.variants (object id=@line.variantId status='active')))}}{{setData 'set' '_transaction' 'variantFound' true}}{{/if}}{{/each}}
  {{#unless (dataRaw '_transaction' 'variantFound')}}{{setData 'set' '_transaction' 'error' 'Select an active product variant.'}}{{/unless}}{{setData 'set' '_transaction' 'variantFound' false}}
  {{setVar 'delta' @line.quantity}}{{#if (eq @type 'stock-out')}}{{setVar 'delta' (multiply @line.quantity -1)}}{{/if}}
  {{#each (dataRaw '_transaction' 'inventory')}}{{#if (eq this.variantId @line.variantId)}}{{#if (eq this.warehouseId @warehouseId)}}
    {{setData 'set' '_transaction' 'recordFound' true}}
    {{#if (lt (add this.onHand @delta) this.reserved)}}{{setData 'set' '_transaction' 'error' 'Insufficient available stock for one or more items.'}}{{/if}}
    {{setData 'set' '_transaction' (concat 'inventory.' @index '.onHand') (add this.onHand @delta)}}
  {{/if}}{{/if}}{{/each}}
  {{#unless (dataRaw '_transaction' 'recordFound')}}
    {{#if (eq @type 'stock-out')}}{{setData 'set' '_transaction' 'error' 'Insufficient available stock for one or more items.'}}{{else}}
      {{setData 'push' '_transaction' 'inventory' (object variantId=@line.variantId warehouseId=@warehouseId onHand=@line.quantity reserved=0)}}
    {{/if}}
  {{/unless}}{{setData 'set' '_transaction' 'recordFound' false}}
  {{setData 'push' '_transaction' 'movements' (object id=(uuid) variantId=@line.variantId warehouseId=@warehouseId type=@type quantity=@delta occurredAt=(now) reversalOfId=null reference=(bodyRaw 'reference') note=(bodyRaw 'note'))}}
{{/each}}
{{#if (dataRaw '_transaction' 'error')}}{{status 422}}{{{stringify (object error=(dataRaw '_transaction' 'error'))}}}{{else}}{{setData 'set' 'inventory' '' (dataRaw '_transaction' 'inventory')}}{{setData 'set' 'stockMovements' '' (concat (dataRaw '_transaction' 'movements') (dataRaw 'stockMovements'))}}{"inventory":{{{data 'inventory'}}},"stockMovements":{{{data 'stockMovements'}}} }{{/if}}{{setData 'set' '_transaction' '' (jsonParse '{}')}}

{{setData 'set' '_transaction' '' (jsonParse '{}')}}
{{setVar 'movement' (lookup (filter (dataRaw 'stockMovements') (object id=(bodyRaw 'id'))) 0)}}
{{#unless @movement}}{{setData 'set' '_transaction' 'error' 'Movement not found.'}}{{/unless}}
{{#if (eq @movement.type 'reversal')}}{{setData 'set' '_transaction' 'error' 'Reversal movements cannot be reversed.'}}{{/if}}
{{#if (len (filter (dataRaw 'stockMovements') (object reversalOfId=(bodyRaw 'id'))))}}{{setData 'set' '_transaction' 'error' 'This movement cannot be reversed or has already been reversed.'}}{{/if}}
{{#unless (bodyRaw 'reason')}}{{setData 'set' '_transaction' 'error' 'Enter a reversal reason.'}}{{/unless}}
{{setData 'set' '_transaction' 'inventory' (jsonParse (stringify (dataRaw 'inventory')))}}
{{#each (dataRaw '_transaction' 'inventory')}}{{#if (eq this.variantId @movement.variantId)}}{{#if (eq this.warehouseId @movement.warehouseId)}}
  {{setData 'set' '_transaction' 'found' true}}
  {{#if (lt (subtract this.onHand @movement.quantity) this.reserved)}}{{setData 'set' '_transaction' 'error' 'This reversal would make available stock negative.'}}{{/if}}
  {{setData 'set' '_transaction' (concat 'inventory.' @index '.onHand') (subtract this.onHand @movement.quantity)}}
{{/if}}{{/if}}{{/each}}
{{#unless (dataRaw '_transaction' 'found')}}{{setData 'set' '_transaction' 'error' 'Inventory record not found.'}}{{/unless}}
{{#if (dataRaw '_transaction' 'error')}}{{status 422}}{{{stringify (object error=(dataRaw '_transaction' 'error'))}}}{{else}}{{setData 'set' 'inventory' '' (dataRaw '_transaction' 'inventory')}}{{setData 'set' 'stockMovements' '' (concat (array (object id=(uuid) variantId=@movement.variantId warehouseId=@movement.warehouseId type='reversal' quantity=(multiply @movement.quantity -1) occurredAt=(now) reversalOfId=@movement.id reference=@movement.reference note=(bodyRaw 'reason'))) (dataRaw 'stockMovements'))}}{"inventory":{{{data 'inventory'}}},"stockMovements":{{{data 'stockMovements'}}} }{{/if}}{{setData 'set' '_transaction' '' (jsonParse '{}')}}

{{setData 'set' '_transaction' '' (jsonParse '{}')}}
{{setVar 'category' (jsonParse (stringify (lookup (filter (dataRaw 'categories') (object id=(bodyRaw 'id'))) 0)))}}
{{#unless @category}}{{setData 'set' '_transaction' 'error' 'Category not found.'}}{{/unless}}
{{setVar 'siblings' (sortBy (filter (dataRaw 'categories') (object parentId=@category.parentId)) 'sortOrder')}}
{{#each @siblings}}{{#if (eq this.id @category.id)}}
  {{#if (eq (bodyRaw 'direction') 'up')}}{{setData 'set' '_transaction' 'other' (lookup @siblings (subtract @index 1))}}{{else}}{{setData 'set' '_transaction' 'other' (lookup @siblings (add @index 1))}}{{/if}}
{{/if}}{{/each}}
{{setVar 'other' (jsonParse (stringify (dataRaw '_transaction' 'other')))}}
{{#unless @other}}{{setData 'set' '_transaction' 'error' 'Category cannot move further in this direction.'}}{{/unless}}
{{#if (dataRaw '_transaction' 'error')}}{{status 422}}{{{stringify (object error=(dataRaw '_transaction' 'error'))}}}{{else}}{{#each (dataRaw 'categories')}}{{#if (eq this.id @category.id)}}{{setData 'set' 'categories' (concat @index '.sortOrder') @other.sortOrder}}{{else}}{{#if (eq this.id @other.id)}}{{setData 'set' 'categories' (concat @index '.sortOrder') @category.sortOrder}}{{/if}}{{/if}}{{/each}}{{{data 'categories'}}}{{/if}}{{setData 'set' '_transaction' '' (jsonParse '{}')}}

{{setData 'set' '_transaction' '' (jsonParse '{}')}}
{{setVar 'key' (bodyRaw 'idempotencyKey')}}
{{setVar 'existing' (lookup (filter (dataRaw 'order-requests') (object key=@key)) 0)}}
{{#if @existing}}{{{stringify @existing.order}}}{{else}}
{{#unless (bodyRaw 'customerName')}}{{setData 'set' '_transaction' 'error' 'Enter a customer name.'}}{{/unless}}
{{#unless (len (filter (array 'ONLINE' 'POS') (bodyRaw 'channel')))}}{{setData 'set' '_transaction' 'error' 'Select a valid order channel.'}}{{/unless}}
{{#unless (len (bodyRaw 'items'))}}{{setData 'set' '_transaction' 'error' 'Add at least one item.'}}{{/unless}}
{{setData 'set' '_transaction' 'items' (array)}}{{setData 'set' '_transaction' 'total' 0}}
{{setData 'set' '_transaction' 'quantities' (jsonParse '{}')}}
{{#each (bodyRaw 'items')}}
  {{setVar 'line' this}}
  {{#unless (gt this.quantity 0)}}{{setData 'set' '_transaction' 'error' 'Quantity must be a positive whole number.'}}{{/unless}}
  {{#unless (eq (modulo this.quantity 1) 0)}}{{setData 'set' '_transaction' 'error' 'Quantity must be a positive whole number.'}}{{/unless}}
  {{setData 'set' '_transaction' 'product' null}}{{setData 'set' '_transaction' 'variant' null}}
  {{#each (dataRaw 'products')}}{{#if (eq this.status 'active')}}
    {{#if (len (filter this.variants (object id=@line.variantId status='active')))}}
      {{setData 'set' '_transaction' 'product' this}}
      {{setData 'set' '_transaction' 'variant' (lookup (filter this.variants (object id=@line.variantId status='active')) 0)}}
    {{/if}}
  {{/if}}{{/each}}
  {{setVar 'product' (dataRaw '_transaction' 'product')}}{{setVar 'variant' (dataRaw '_transaction' 'variant')}}
  {{#unless @variant}}{{setData 'set' '_transaction' 'error' 'Select an active product variant.'}}{{/unless}}
  {{setData 'set' '_transaction' 'available' 0}}
  {{#each (filter (dataRaw 'inventory') (object variantId=@line.variantId))}}{{setData 'set' '_transaction' 'available' (add (dataRaw '_transaction' 'available') (subtract this.onHand this.reserved))}}{{/each}}
  {{setData 'set' '_transaction' (concat 'quantities.' @line.variantId) (add (dataRaw '_transaction' (concat 'quantities.' @line.variantId)) @line.quantity)}}
  {{#if (gt (dataRaw '_transaction' (concat 'quantities.' @line.variantId)) (dataRaw '_transaction' 'available'))}}{{setData 'set' '_transaction' 'error' 'Insufficient available stock. Review the cart and retry.'}}{{/if}}
  {{setVar 'image' null}}{{#if (len @product.images)}}{{setVar 'image' (lookup (lookup @product.images 0) 'url')}}{{/if}}
  {{setVar 'total' (multiply @line.quantity @variant.price)}}
  {{setData 'set' '_transaction' 'total' (add (dataRaw '_transaction' 'total') @total)}}
  {{setData 'push' '_transaction' 'items' (object id=(uuid) productId=@product.id variantId=@variant.id sku=@variant.sku productName=@product.name variantName=@variant.name imageUrl=@image quantity=@line.quantity unitPrice=@variant.price lineDiscount=0 lineTotal=@total)}}
{{/each}}
{{#if (dataRaw '_transaction' 'error')}}{{status 422}}{{{stringify (object error=(dataRaw '_transaction' 'error'))}}}{{else}}{{setData 'inc' 'order-sequence' '' 1}}{{setVar 'id' (uuid)}}{{setVar 'total' (dataRaw '_transaction' 'total')}}
{{setVar 'order' (object id=@id orderNumber=(concat 'ORD-' (now 'yyyy') '-' (padStart (dataRaw 'order-sequence') 6 '0')) channel=(bodyRaw 'channel') currency='IDR' status='PENDING' paymentStatus='PENDING' customerId=null customerSnapshot=(object name=(bodyRaw 'customerName') email=(bodyRaw 'customerEmail' null) phone=(bodyRaw 'customerPhone' null)) shippingAddressSnapshot=null items=(dataRaw '_transaction' 'items') totals=(object subtotal=@total discountTotal=0 shippingTotal=0 grandTotal=@total) createdAt=(now) statusHistory=(array (object id=(uuid) orderId=@id fromStatus=null toStatus='PENDING' occurredAt=(now) note='Order created through API.')))}}
{{#if (eq (bodyRaw 'fulfillment') 'PICKUP')}}{{setVar 'order' (objectMerge @order (object fulfillment='PICKUP'))}}{{/if}}
{{setData 'set' 'orders' '' (concat (array @order) (dataRaw 'orders'))}}
{{#if @key}}{{setData 'push' 'order-requests' '' (object key=@key order=@order)}}{{/if}}
{{{stringify @order}}}{{/if}}{{setData 'set' '_transaction' '' (jsonParse '{}')}}{{/if}}

