  {{setData 'set' '_transaction' 'available' 0}}
  {{#each (filter (dataRaw 'inventory') (object variantId=@line.variantId))}}{{setData 'set' '_transaction' 'available' (add (dataRaw '_transaction' 'available') (subtract this.onHand this.reserved))}}{{/each}}
  {{setData 'set' '_transaction' (concat 'quantities.' @line.variantId) (add (dataRaw '_transaction' (concat 'quantities.' @line.variantId)) @line.quantity)}}
  {{#if (gt (dataRaw '_transaction' (concat 'quantities.' @line.variantId)) (dataRaw '_transaction' 'available'))}}{{setData 'set' '_transaction' 'error' 'Insufficient available stock. Review the cart and retry.'}}{{/if}}
  {{setVar 'image' null}}{{#if (len @product.images)}}{{setVar 'image' (lookup (lookup @product.images 0) 'url')}}{{/if}}
  {{setVar 'total' (multiply @line.quantity @variant.price)}}
